function v28Code(){
  const v=document.getElementById('language')?.value||'English';
  const s=v.toLowerCase();
  if(s.includes('ewe')||s.includes('eʋ')) return 'ewe';
  if(s.includes('kaby')||s.includes('kab')) return 'kab';
  if(s.includes('fran')) return 'fr';
  if(s.includes('portu')) return 'pt';
  return 'en';
}
