function v28TranslateAll(){
  const code=v28Code(),dict=V28[code]||V28.en;
  document.documentElement.lang=code;
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);
  while(walker.nextNode()){
    const n=walker.currentNode;
    if(['SCRIPT','STYLE','CODE','TEXTAREA'].includes(n.parentElement?.tagName)) continue;
    if(!n._v28original) n._v28original=n.nodeValue;
    const original=n._v28original.trim();
    // Restore source text first so switching languages is reversible.
    if(original) n.nodeValue=n.nodeValue.replace(n.nodeValue.trim(),original);
    v28TranslateNode(n,dict);
  }
  document.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(el=>{
    if(!el.dataset.v28original) el.dataset.v28original=el.placeholder;
    const o=el.dataset.v28original.trim();
    el.placeholder=(dict[o]||o);
  });
  // Translate select option labels as well.
  document.querySelectorAll('select option').forEach(o=>{
    if(!o.dataset.v28original) o.dataset.v28original=o.textContent;
    const x=o.dataset.v28original.trim();
    o.textContent=dict[x]||x;
  });
}
function languageChanged(){
  v28TranslateAll();
  // Dynamic pages (UNICEF/WHO, marketplace, payments, nutritionist) are re-rendered,
  // then translated again so their newly created text also changes.
  try{renderUNICEF();renderWHO();}catch(e){}
  try{renderPayments(document.getElementById('country')?.value);}catch(e){}
  setTimeout(v28TranslateAll,30);
}
function renderPayments(c){
  const root=document.getElementById('paymentMethods'); if(!root)return;
  const list=payment[c]||["Bank Card"];
  const countryName=(countries.find(a=>a[0]===c)||[c,c])[1];
  root.innerHTML=list.map((x,i)=>{
    const icon=x==="Bank Card"?"💳":(x.includes("Bank")?"🏦":(x==="OPay"||x==="PalmPay"?"👛":"📱"));
    return `<div class="card payment-method-card" data-payment-method="${x.replace(/"/g,'&quot;')}">
      <div style="display:flex;align-items:center;gap:12px">
        <div style="font-size:25px">${icon}</div>
        <div><h3 style="margin:0">${x}</h3><p class="muted" style="margin:4px 0 0">Available for ${countryName}</p></div>
      </div>
      <button class="btn primary" onclick="selectPayment('${x.replace(/'/g,"\'")}')" data-i18n="ui.select">Select</button>
    </div>`;
  }).join('');
}
function selectPayment(method){
  const c=document.getElementById('country')?.value||'TG';
  toast('Checkout selected: '+method+' • '+((countries.find(a=>a[0]===c)||[c,c])[1]));
}
