const V29_BASE_TEXT=new WeakMap();
function v29LanguageCode(){
 const s=document.getElementById('language')||document.getElementById('lang')||document.querySelector('select[name="language"]')||document.querySelector('select[id*="language" i]');
 return (s?.value||window.currentLanguage||'en').toLowerCase().split(/[-_]/)[0];
}
function v29Capture(root=document.body){
 const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
 while(w.nextNode()){
   const n=w.currentNode, p=n.parentElement;
   if(!p||['SCRIPT','STYLE','CODE','NOSCRIPT','TEXTAREA'].includes(p.tagName)) continue;
   if(!V29_BASE_TEXT.has(n)) V29_BASE_TEXT.set(n,n.nodeValue);
 }
}
function v29TranslateAll(){
 v29Capture();
 const lang=v29LanguageCode(), dict=V29_I18N[lang]||V29_I18N.en;
 document.documentElement.lang=lang;
 V29_BASE_TEXT.forEach((base,n)=>{
   if(!n.isConnected)return;
   const trimmed=base.trim();
   if(!trimmed||trimmed.length>260)return;
   let translated=dict[trimmed];
   if(!translated){
     // Translate common text containing a known label, preserving surrounding punctuation.
     translated=trimmed;
     const keys=Object.keys(dict).sort((a,b)=>b.length-a.length);
     for(const k of keys){
       if(translated.includes(k)){translated=translated.split(k).join(dict[k]);}
     }
   }
   if(translated&&translated!==trimmed){
     n.nodeValue=base.replace(trimmed,translated);
   } else if(lang==='en'){
     n.nodeValue=base;
   }
 });
 document.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(el=>{
   const base=el.dataset.v29BasePlaceholder||el.getAttribute('placeholder')||'';
   el.dataset.v29BasePlaceholder=base;
   el.setAttribute('placeholder',dict[base]||base);
 });
}
function v29Install(){
 v29Capture();
 const selectors=[
 document.getElementById('language'),document.getElementById('lang'),
 document.querySelector('select[name="language"]'),document.querySelector('select[id*="language" i]')
 ].filter(Boolean);
 selectors.forEach(s=>s.addEventListener('change',()=>setTimeout(v29TranslateAll,10)));
 // Add official languages if absent; preserve existing local-language options.
 selectors.forEach(s=>{
   const vals=[...s.options].map(o=>o.value.toLowerCase());
   if(!vals.includes('en')){const o=document.createElement('option');o.value='en';o.textContent='English';s.appendChild(o)}
   if(!vals.includes('fr')){const o=document.createElement('option');o.value='fr';o.textContent='Français';s.appendChild(o)}
   if(!vals.includes('es')){const o=document.createElement('option');o.value='es';o.textContent='Español';s.appendChild(o)}
 });
 v29TranslateAll();
 new MutationObserver(()=>setTimeout(v29TranslateAll,0)).observe(document.body,{childList:true,subtree:true});
}

