/* ============================================================
   NUTRI.N°1 V33 — PRODUCTION LOCALIZATION SYSTEM
   Explicit i18n keys only. No automatic text detection.
   ============================================================ */
window.NUTRI_I18N = {
  locale: localStorage.getItem('nutri_language') || 'en',
  dictionaries: {},
  async load(locale){
    locale=(locale||'en').toLowerCase();
    if(this.dictionaries[locale]) return this.dictionaries[locale];
    const r=await fetch('./locales/'+locale+'.json?v=33',{cache:'no-store'});
    if(!r.ok) throw new Error('Locale '+locale+' not found');
    this.dictionaries[locale]=await r.json();
    return this.dictionaries[locale];
  },
  async init(){
    await this.load('en');
    const selector=document.getElementById('language')||document.getElementById('lang')||
      document.querySelector('select[name="language"]')||document.querySelector('select[id*="language" i]');
    if(selector){
      const opts=[['en','English'],['fr','Français'],['es','Español'],['ewe','Eʋegbe / Ewe'],['kab','Kabyè']];
      opts.forEach(([v,n])=>{if(![...selector.options].some(o=>o.value.toLowerCase()===v)){
        const o=document.createElement('option');o.value=v;o.textContent=n;selector.appendChild(o);
      }});
      selector.value=this.locale;
      selector.addEventListener('change',e=>this.setLocale(e.target.value));
    }
    await this.setLocale(this.locale,false);
  },
  t(key, params={}){
    const d=this.dictionaries[this.locale]||this.dictionaries.en||{};
    let s=d[key] ?? (this.dictionaries.en||{})[key] ?? key;
    Object.entries(params).forEach(([k,v])=>{s=s.replaceAll('{'+k+'}',String(v))});
    return s;
  },
  async setLocale(locale, rerender=true){
    locale=(locale||'en').toLowerCase();
    await this.load(locale);
    this.locale=locale; localStorage.setItem('nutri_language',locale);
    document.documentElement.lang=locale;
    this.render();
    document.dispatchEvent(new CustomEvent('nutri:i18nChanged',{detail:{locale}}));
  },
  render(root=document){
    root.querySelectorAll?.('[data-i18n]').forEach(el=>{
      const key=el.dataset.i18n;
      if(el.tagName==='INPUT'||el.tagName==='TEXTAREA') return;
      el.textContent=this.t(key);
    });
    root.querySelectorAll?.('[data-i18n-placeholder]').forEach(el=>{
      el.placeholder=this.t(el.dataset.i18nPlaceholder);
    });
    root.querySelectorAll?.('[data-i18n-title]').forEach(el=>{
      el.title=this.t(el.dataset.i18nTitle);
    });
    root.querySelectorAll?.('[data-i18n-aria]').forEach(el=>{
      el.setAttribute('aria-label',this.t(el.dataset.i18nAria));
    });
  },
  // Use this after a module renders HTML dynamically.
  renderModule(root){ this.render(root||document); }
};
document.addEventListener('DOMContentLoaded',()=>NUTRI_I18N.init().catch(console.error));



/* V34 FINAL — Country selector is embedded, so it works from file:// and hosted deployments. */
window.NUTRI_V34_COUNTRY={
 manifest:window.NUTRI_V34_MANIFEST,
 countrySelect(){return document.getElementById('country')||document.getElementById('countrySelector')||document.querySelector('select[name="country"]')||document.querySelector('select[id*="country" i]')},
 languageSelect(){return document.getElementById('language')||document.getElementById('lang')||document.querySelector('select[name="language"]')||document.querySelector('select[id*="language" i]')},
 init(){
   this.ensureCountry();
   this.rebuildLanguages(this.countrySelect().value);
   this.bind();
 },
 ensureCountry(){
   let s=this.countrySelect();
   if(!s){
     const host=document.querySelector('.topbar,.header,.toolbar,.controls,.hero,.app-header')||document.body;
     const wrap=document.createElement('label');wrap.className='v34-country-control';
     wrap.innerHTML='<span>Country</span><select id="countrySelector"></select>';
     host.prepend(wrap);s=wrap.querySelector('select');
   }
   const saved=localStorage.getItem('nutri_country')||s.value||this.manifest.defaultCountry;
   s.innerHTML=this.manifest.countries.map(c=>`<option value="${c.code}">${c.name}</option>`).join('');
   s.value=this.manifest.countries.some(c=>c.code===saved)?saved:this.manifest.defaultCountry;
   localStorage.setItem('nutri_country',s.value);
 },
 available(code){
   const c=this.manifest.countries.find(x=>x.code===code);
   return c?[...new Set([...(c.official||[]),...(c.local||[])])]:['en'];
 },
 rebuildLanguages(code){
   const s=this.languageSelect();if(!s)return;
   const langs=this.available(code), saved=localStorage.getItem('nutri_language');
   const c=this.manifest.countries.find(x=>x.code===code);
   s.innerHTML=langs.map(x=>`<option value="${x}">${this.manifest.languageLabels[x]||x}</option>`).join('');
   s.value=langs.includes(saved)?saved:(c?.default||langs[0]);
   localStorage.setItem('nutri_language',s.value);
   if(window.NUTRI_I18N?.setLocale) window.NUTRI_I18N.setLocale(s.value,false);
 },
 bind(){
   const c=this.countrySelect(),l=this.languageSelect();
   c?.addEventListener('change',()=>{localStorage.setItem('nutri_country',c.value);this.rebuildLanguages(c.value);document.dispatchEvent(new CustomEvent('nutri:countryChanged',{detail:{country:c.value,languages:this.available(c.value)}}))});
   l?.addEventListener('change',()=>{localStorage.setItem('nutri_language',l.value);if(window.NUTRI_I18N?.setLocale)window.NUTRI_I18N.setLocale(l.value,false)});
 }
};
document.addEventListener('DOMContentLoaded',()=>setTimeout(()=>NUTRI_V34_COUNTRY.init(),120));



/* V34 FINAL — locale dictionaries are embedded; fetch is only a fallback. */
document.addEventListener('DOMContentLoaded',()=>{
 setTimeout(()=>{
   if(!window.NUTRI_I18N)return;
   const oldLoad=window.NUTRI_I18N.load.bind(window.NUTRI_I18N);
   window.NUTRI_I18N.load=async function(locale){
     locale=(locale||'en').toLowerCase();
     if(window.NUTRI_EMBEDDED_LOCALES && window.NUTRI_EMBEDDED_LOCALES[locale]){
       this.dictionaries[locale]=window.NUTRI_EMBEDDED_LOCALES[locale];
       return this.dictionaries[locale];
     }
     return oldLoad(locale);
   };
   // Re-apply current selection after override so FR/ES work immediately.
   const s=document.getElementById('language')||document.getElementById('lang')||document.querySelector('select[name="language"]');
   this.setLocale(s?.value||localStorage.getItem('nutri_language')||'en',false);
 },180);
});



