/* NUTRI.N°1 V39 — V20 Dynamic Experience Restoration
   Restores interactive KPI cards, charts, filters and live demo behavior across the
   core pages while preserving V37 country/language/payment architecture. */
(function(){
 const q=s=>document.querySelector(s), qa=s=>[...document.querySelectorAll(s)];
 const colors={}; // intentionally no fixed chart colors: use CSS/default chart palette.

 const pageDefs=[
  {keys:["Executive Home"],title:"Executive Home",type:"exec"},
  {keys:["Citizen Dashboard 360"],title:"Citizen Dashboard 360°",type:"citizen"},
  {keys:["Connected Devices"],title:"Connected Devices",type:"devices"},
  {keys:["AI Food & Meal Scanner"],title:"AI Food & Meal Scanner",type:"scanner"},
  {keys:["AI Nutrition & Prevention"],title:"AI Nutrition & Prevention",type:"nutrition"},
  {keys:["Nutritionist Network"],title:"Nutritionist Network",type:"nutritionist"},
  {keys:["Healthy Food Marketplace"],title:"Healthy Food Marketplace",type:"market"},
  {keys:["African Food Cloud"],title:"African Food Cloud",type:"cloud"},
  {keys:["Ministry of health Command Center"],title:"Ministry of health Command Center",type:"health"},
  {keys:["Ministry of Agriculture Food intelligence"],title:"Ministry of Agriculture Food intelligence",type:"agri"},
  {keys:["Research & Evidence Graph"],title:"Research & Evidence Graph",type:"research"},
  {keys:["UNICEF Nutrition Intelligence Center"],title:"UNICEF Nutrition Intelligence Center",type:"unicef"},
  {keys:["WHO Nutrition & NCD Intelligence Center"],title:"WHO Nutrition & NCD Intelligence Center",type:"who"}
 ];

 function visibleSection(def){
   const all=qa("section,main,[role='main'],.page,.view,.content");
   return all.find(el=>{
     const t=(el.innerText||"").toLowerCase();
     return def.keys.some(k=>t.includes(k.toLowerCase()));
   });
 }
 function ensureCanvas(root,id){
   let c=root.querySelector("#"+id);
   if(!c){
     const wrap=document.createElement("div"); wrap.className="v38-chart-wrap";
     c=document.createElement("canvas"); c.id=id; c.height=220; wrap.appendChild(c);
     root.appendChild(wrap);
   }
   return c;
 }
 function chart(root,id,type,labels,data,label){
   const c=ensureCanvas(root,id);
   if(window.Chart){
     const old=window.Chart.getChart?.(c); if(old) old.destroy();
     new Chart(c,{type,data:{labels,datasets:[{label,data,borderWidth:2,tension:.35,fill:type==="line"}]},
       options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:true}},
       scales:{y:{beginAtZero:true}}}});
   }else{
     // Lightweight SVG fallback so graphs remain visible without an external CDN.
     const max=Math.max(...data,1), w=720,h=210,p=28;
     const svg=document.createElementNS("http://www.w3.org/2000/svg","svg");
     svg.setAttribute("viewBox",`0 0 ${w} ${h}`); svg.setAttribute("class","v38-svg-chart");
     const pts=data.map((v,i)=>`${p+i*(w-2*p)/(data.length-1||1)},${h-p-(v/max)*(h-2*p)}`).join(" ");
     const poly=document.createElementNS("http://www.w3.org/2000/svg","polyline");
     poly.setAttribute("points",pts);poly.setAttribute("fill","none");poly.setAttribute("stroke","currentColor");poly.setAttribute("stroke-width","3");
     svg.appendChild(poly); c.replaceWith(svg);
   }
 }
 function cards(root,items){
   if(root.querySelector(".v38-kpis"))return;
   const wrap=document.createElement("div");wrap.className="v38-kpis";
   wrap.innerHTML=items.map(x=>`<div class="v38-kpi"><div class="v38-kpi-label">${x[0]}</div><div class="v38-kpi-value">${x[1]}</div><div class="v38-kpi-trend">${x[2]||"Live demo data"}</div></div>`).join("");
   root.insertBefore(wrap,root.firstChild);
 }
 function addControls(root,type){
   if(root.querySelector(".v38-controls"))return;
   const c=document.createElement("div");c.className="v38-controls";
   c.innerHTML=`<span class="v38-live"><i></i> Live data</span>
   <select class="v38-period"><option>Last 7 days</option><option>Last 30 days</option><option>Last 90 days</option><option>This year</option></select>
   <button type="button" class="btn primary v38-refresh">Refresh</button>`;
   root.insertBefore(c,root.firstChild);
   c.querySelector(".v38-refresh").onclick=()=>{c.querySelector(".v38-live").classList.add("pulse");setTimeout(()=>c.querySelector(".v38-live").classList.remove("pulse"),500);renderType(root,type,true)};
 }
 function renderType(root,type){
   addControls(root,type);
   const datasets={
    exec:[["Active citizens","128,420","+12.4%"],["Countries","15","ECOWAS + AES"],["Food records","1.82M","+8.7%"],["Prevention plans","42,860","+15.1%"]],
    citizen:[["BMI","23.8","Within reference range"],["Blood glucose","5.4 mmol/L","Latest reading"],["Blood pressure","118/76","Latest reading"],["Nutrition score","82/100","+6 points"]],
    devices:[["Connected devices","4","2 syncing now"],["Glucose readings","126","This month"],["BP readings","94","This month"],["Sync status","98.7%","Successful"]],
    scanner:[["Foods identified","98.4%","AI confidence"],["Meals analyzed","3,842","This month"],["Avg. calories","486 kcal","Per meal"],["Nutrition completeness","91%","Database match"]],
    nutrition:[["Plans generated","2,480","Personalized"],["Prevention score","78/100","+9 points"],["Risk flags","186","Needs review"],["Adherence","84%","+5.2%"]],
    nutritionist:[["Active patients","1,284","+11.8%"],["Appointments","326","This week"],["Teleconsultations","198","This month"],["Response time","18 min","Median"]],
    market:[["Healthy products","2,460","Across countries"],["Traceable products","94%","Verified"],["Orders","8,420","+18.3%"],["Nutrition categories","12","Active"]],
    cloud:[["Food records","1.82M","+8.7%"],["Recipes","46,820","+4.1%"],["Lab analyses","18,640","+12.2%"],["Validated foods","92%","Expert validated"]],
    health:[["Children monitored","248,620","+9.1%"],["Double burden","18.6%","Population indicator"],["Maternal malnutrition","12.4%","Latest estimate"],["NCD risk","27.8%","+2.3%"]],
    agri:[["Cereals","1.24M t","Production"],["Tubers","2.08M t","Production"],["Fruits & vegetables","1.12M t","Production"],["Legumes & oilseeds","0.86M t","Production"]],
    research:[["Evidence nodes","18,420","+7.8%"],["Studies","3,842","Indexed"],["Food-disease links","12,640","+11.4%"],["Validated evidence","86%","Expert reviewed"]],
    unicef:[["Children monitored","248,620","+9.1%"],["0–6 months","92.4%","Exclusive breastfeeding"],["6–24 months","18.2%","Malnutrition indicator"],["Women maternal","12.4%","Malnutrition indicator"]],
    who:[["Diabetes","8.7%","Population indicator"],["Hypertension","21.4%","Population indicator"],["Obesity","12.8%","Population indicator"],["Cardiovascular risk","16.2%","Population indicator"]]
   };
   cards(root,datasets[type]||datasets.exec);
   const id="v38-"+type;
   const labs=type==="agri"?["Cereals","Tubers","Fruits & vegetables","Legumes","Oilseeds"]:
     type==="health"||type==="unicef"?["0–6m","6–24m","24–59m","5–12y","12y+"]:
     type==="who"?["Diabetes","Hypertension","Obesity","Cancer","CKD","Stroke"]:
     ["Jan","Feb","Mar","Apr","May","Jun","Jul"];
   const dat=type==="agri"?[62,88,54,42,36]:
     type==="health"||type==="unicef"?[18,25,22,14,9]:
     type==="who"?[42,58,36,28,19,24]:[32,45,38,58,52,71,66];
   chart(root,id,type==="agri"||type==="health"||type==="unicef"||type==="who"?"bar":"line",labs,dat,"Indicator");
 }
 function activate(){
   pageDefs.forEach(def=>{const root=visibleSection(def); if(root)renderType(root,def.type)});
 }
 window.NUTRI_V39_REFRESH=()=>{activate();};
 document.addEventListener("DOMContentLoaded",()=>setTimeout(activate,450));
 document.addEventListener("nutri:countryChanged",()=>setTimeout(activate,250));
})();



/* ============================================================
   NUTRI.N°1 V41 — TRUE INTERACTIVE DEMO LAYER
   Scanner animation + AI plan generation + nutritionist filtering/chat
   + Ministry of Health interactive charts.
   ============================================================ */
(function(){
  const $=s=>document.querySelector(s), $$=s=>Array.from(document.querySelectorAll(s));
  const countries=[
    ["TG","Togo"],["BJ","Benin"],["BF","Burkina Faso"],["CV","Cabo Verde"],
    ["CI","Côte d'Ivoire"],["GM","The Gambia"],["GH","Ghana"],["GN","Guinea"],
    ["GW","Guinea-Bissau"],["LR","Liberia"],["ML","Mali"],["MR","Mauritania"],
    ["NE","Niger"],["NG","Nigeria"],["SN","Senegal"],["SL","Sierra Leone"]
  ];
  const specialties=["General Nutrition","Maternal & Child Nutrition","Diabetes Nutrition","Cardiovascular Nutrition","Renal Nutrition","Sports Nutrition","Clinical Nutrition","Malnutrition"];

  function existingButton(match){
    return $$('button').find(b=>(b.textContent||'').toLowerCase().includes(match));
  }

  /* ---------- AI FOOD & MEAL SCANNER ---------- */
  function scannerUI(){
    const buttons=$$('button').filter(b=>{
      const t=(b.textContent||'').toLowerCase();
      return t.includes('scan food')||t.includes('scan meal')||t.includes('start scan')||t.includes('scan now');
    });
    buttons.forEach(btn=>{
      if(btn.dataset.v41scan)return; btn.dataset.v41scan=1;
      btn.addEventListener('click',()=>{
        let host=btn.closest('.card,.panel,section,div');
        let stage=host?.querySelector('.v41-scan-stage');
        if(!stage){
          stage=document.createElement('div');stage.className='v41-scan-stage';
          stage.innerHTML=`<div class="v41-scanner-visual"><div class="v41-scan-grid"></div><div class="v41-scan-line"></div></div>
          <div style="display:flex;justify-content:space-between;margin-top:10px"><strong class="v41-scan-status">Initializing AI scan…</strong><span class="v41-scan-percent">0%</span></div>
          <div class="progress" style="margin-top:7px"><div class="progress-fill" style="width:0%"></div></div>
          <div class="v41-scan-result"></div>`;
          (host||document.body).appendChild(stage);
        }
        stage.classList.add('on');
        const status=stage.querySelector('.v41-scan-status'), pct=stage.querySelector('.v41-scan-percent'), fill=stage.querySelector('.progress-fill'), result=stage.querySelector('.v41-scan-result');
        result.innerHTML='';let p=0;
        const phases=['Initializing camera / image stream…','Detecting food or meal…','Recognizing ingredients…','Estimating portion sizes…','Calculating nutrients…','Generating nutrition insight…'];
        clearInterval(stage._timer);
        stage._timer=setInterval(()=>{
          p=Math.min(100,p+Math.floor(Math.random()*13)+7);pct.textContent=p+'%';fill.style.width=p+'%';
          status.textContent=phases[Math.min(phases.length-1,Math.floor(p/18))];
          if(p>=100){
            clearInterval(stage._timer);
            result.innerHTML=`<div class="card v41-result-card"><strong>AI scan completed</strong>
              <div style="margin-top:7px">Detected meal: <b>Local balanced meal</b></div>
              <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:10px">
              <div><small>Energy</small><br><b>428 kcal</b></div><div><small>Protein</small><br><b>18.6 g</b></div>
              <div><small>Carbohydrate</small><br><b>62.4 g</b></div><div><small>Fiber</small><br><b>10.2 g</b></div></div>
              <div class="muted" style="margin-top:8px">Review the AI estimate before using it for clinical or dietary decisions.</div></div>`;
          }
        },480);
      });
    });
  }

  /* ---------- AI NUTRITION & PREVENTION ---------- */
  function planUI(){
    const buttons=$$('button').filter(b=>(b.textContent||'').toLowerCase().includes('generate personalized plan'));
    buttons.forEach(btn=>{
      if(btn.dataset.v41plan)return;btn.dataset.v41plan=1;
      btn.addEventListener('click',()=>{
        let host=btn.closest('.card,.panel,section,div')||document.body;
        let out=host.querySelector('.v41-plan-output');
        if(!out){out=document.createElement('div');out.className='v41-plan-output';host.appendChild(out)}
        out.innerHTML='<div class="muted v41-plan-step" style="margin-top:10px">AI is combining your profile, country food database, goals and prevention signals…</div>';
        setTimeout(()=>{
          const days=[
            ['Monday','Millet porridge','Beans + vegetables + orange-fleshed sweet potato','Fruit + unsweetened yogurt'],
            ['Tuesday','Whole-grain corn porridge','Fish/legume stew + leafy vegetables','Groundnut-based snack + fruit'],
            ['Wednesday','Sorghum porridge + fruit','Rice + beans + mixed vegetables','Sweet potato + vegetable soup'],
            ['Thursday','Millet + groundnut paste','Tubers + legumes + leafy greens','Fruit + nuts'],
            ['Friday','Corn + beans','Fish/legume + vegetables','Sorghum-based family meal'],
            ['Saturday','Sweet potato + egg/legume','Beans + vegetables + fruit','Light local balanced meal'],
            ['Sunday','Local balanced breakfast','Family meal adapted to profile','Fruit + water']
          ];
          out.innerHTML=`<div class="card v41-result-card"><h3 style="margin-top:0">Your 7-day personalized plan</h3>
          <div class="muted">Generated from the current profile and African food intelligence.</div>
          ${days.map((d,i)=>`<div class="card v41-plan-step" style="margin-top:8px;animation-delay:${i*90}ms"><strong>${d[0]}</strong><div style="margin-top:5px">Breakfast: ${d[1]}</div><div>Lunch: ${d[2]}</div><div>Dinner: ${d[3]}</div></div>`).join('')}</div>`;
        },900);
      });
    });
  }

  /* ---------- NUTRITIONIST NETWORK ---------- */
  function nutritionistUI(){
    const page=$('#nutritionists')||$$('.view').find(v=>(v.textContent||'').toLowerCase().includes('nutritionist network'));
    if(!page)return;
    const controls=page.querySelector('.v41-nutritionist-controls')||document.createElement('div');
    if(!controls.parentNode){
      controls.className='v41-nutritionist-controls v41-toolbar';
      controls.innerHTML=`<select class="v41-country-filter"><option value="">All countries</option>${countries.map(c=>`<option value="${c[0]}">${c[1]}</option>`).join('')}</select>
      <select class="v41-specialty-filter"><option value="">All specialties</option>${specialties.map(s=>`<option>${s}</option>`).join('')}</select>`;
      const heading=page.querySelector('h1,h2,h3');heading?.after(controls);
    }
    const country=controls.querySelector('.v41-country-filter'), spec=controls.querySelector('.v41-specialty-filter');
    const list=page.querySelector('.nutritionist-list')||page.querySelector('[data-nutritionists]')||page.querySelector('.grid3');
    if(!list)return;
    const data=[
      ['Dr. Ama Mensah','GH','Clinical Nutrition'],['Dr. Kossi Afi','TG','Diabetes Nutrition'],
      ['Dr. Awa Diop','SN','Maternal & Child Nutrition'],['Dr. Ibrahim Diallo','GN','Renal Nutrition'],
      ['Dr. Mariam Traoré','ML','Malnutrition'],['Dr. Chinedu Okafor','NG','Cardiovascular Nutrition'],
      ['Dr. Fatou Koné','CI','General Nutrition'],['Dr. Jean Kabore','BF','Clinical Nutrition']
    ];
    const render=()=>{
      const rows=data.filter(x=>(!country.value||x[1]===country.value)&&(!spec.value||x[2]===spec.value));
      list.innerHTML=rows.map(x=>`<div class="card nutritionist-card"><h3>${x[0]}</h3><div>${countries.find(c=>c[0]===x[1])?.[1]||x[1]}</div><div class="muted">${x[2]}</div><button class="btn primary v41-chat-open">Chat</button></div>`).join('');
      list.querySelectorAll('.v41-chat-open').forEach(b=>b.addEventListener('click',()=>openChat(b.closest('.nutritionist-card'))));
    };
    country.addEventListener('change',render);spec.addEventListener('change',render);render();
  }
  function openChat(card){
    let chat=document.getElementById('v41-chat-panel');
    if(!chat){chat=document.createElement('div');chat.id='v41-chat-panel';chat.className='card';
      chat.innerHTML=`<h3 style="margin-top:0">Nutritionist chat</h3><div class="v41-chat" id="v41-chat-messages"><div class="v41-chat-msg assistant">Hello. I’m ready to discuss your nutrition goals and prepare your consultation.</div></div><div class="v41-chat-input"><input id="v41-chat-input" placeholder="Type your message…"><button class="btn primary" id="v41-chat-send">Send</button></div>`;
      document.body.appendChild(chat);
      $('#v41-chat-send').addEventListener('click',sendChat);
      $('#v41-chat-input').addEventListener('keydown',e=>{if(e.key==='Enter')sendChat()});
    }
    chat.querySelector('h3').textContent='Chat with '+card.querySelector('h3').textContent;
    chat.scrollIntoView({behavior:'smooth',block:'center'});
  }
  function sendChat(){
    const input=$('#v41-chat-input'),box=$('#v41-chat-messages');if(!input||!box||!input.value.trim())return;
    const msg=input.value.trim();box.innerHTML+=`<div class="v41-chat-msg user">${msg}</div>`;
    input.value='';setTimeout(()=>{box.innerHTML+=`<div class="v41-chat-msg assistant">Thank you. Your message has been received. The nutritionist can review your profile and continue the consultation.</div>`;box.scrollTop=box.scrollHeight},650);
  }

  /* ---------- MINISTRY OF HEALTH ---------- */
  function healthCharts(){
    const view=$('#health');if(!view)return;
    const chartData=[
      ['Children — double burden',[34,29,24,20,18,16],['0–6m','6–24m','24–59m','5–12y','12–18y','Adults']],
      ['Pregnant & lactating women',[18,21,19,23,20,17],['Q1','Q2','Q3','Q4','Q1','Q2']],
      ['NCD trends',[42,47,51,56,61,66],['2021','2022','2023','2024','2025','2026']]
    ];
    const hosts=[];
    chartData.forEach((d,i)=>{
      let h=$$(`#health .card,#health section`).find(x=>(x.textContent||'').toLowerCase().includes(d[0].toLowerCase()));
      let canvas=h?.querySelector('canvas');
      if(!canvas){
        const all=$$('#health canvas');canvas=all[i];
      }
      if(canvas)hosts.push([canvas,d]);
    });
    hosts.forEach(([canvas,d])=>{
      const ctx=canvas.getContext('2d');
      if(!ctx)return;
      const existing=canvas.__v41chart;if(existing)try{existing.destroy()}catch(e){}
      if(window.Chart){
        canvas.__v41chart=new Chart(ctx,{type:'line',data:{labels:d[2],datasets:[{label:d[0],data:d[1],tension:.35,fill:true}]},
        options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{display:true}},scales:{y:{beginAtZero:true}}}});
      }
    });
  }

  function refresh(id){
    scannerUI();planUI();nutritionistUI();
    if(id==='health'||id==='ministry-health'||id==='healthCommand')setTimeout(healthCharts,100);
  }
  window.NUTRI_V41_REFRESH=refresh;
  document.addEventListener('DOMContentLoaded',()=>setTimeout(()=>refresh(),500));
  // Rebind after dynamic navigation/rendering.
  new MutationObserver(()=>{clearTimeout(window.__v41m);window.__v41m=setTimeout(()=>refresh(),180)})
    .observe(document.body,{subtree:true,childList:true});
})();



